import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';
import { CommandeService } from 'src/app/services/commande.service';

@Component({
  selector: 'app-medicament-list',
  templateUrl: './medicament-list.component.html',
  styleUrls: ['./medicament-list.component.css']
})
export class MedicamentListComponent implements OnInit {
  medicaments: Medicament[] = [];  // ✅ Initialize as an empty array
  fournisseurId: number = 0;
  selectedMedicaments: { medicamentId: number, quantite: number }[] = [];

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute,
    private commandeService: CommandeService
  ) {}

  ngOnInit(): void {
    // Retrieve the fournisseur ID from the route parameters
    this.fournisseurId = Number(this.route.snapshot.paramMap.get('id'));  // ✅ Convert safely to number
    if (this.fournisseurId) {
      this.getMedicamentsByFournisseur(this.fournisseurId);
    }
  }

  // Get medicaments of a specific fournisseur
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(
      data => {
        this.medicaments = data || []; // ✅ Ensure it's always an array
      },
      error => {
        console.error('Erreur lors de la récupération des médicaments', error);
        this.medicaments = []; // ✅ Fallback to an empty array if there's an error
      }
    );
  }

  // Update the selection of medicaments with quantities
  updateSelection(medicamentId: number, event: Event): void {
    const inputElement = event.target as HTMLInputElement;  // ✅ Correct type assertion
    const quantite = Number(inputElement.value);  // ✅ Convert value safely

    if (isNaN(quantite) || quantite < 1) return; // ✅ Prevent invalid input

    const existing = this.selectedMedicaments.find(item => item.medicamentId === medicamentId);
    if (existing) {
      existing.quantite = quantite;
    } else {
      this.selectedMedicaments.push({ medicamentId, quantite });
    }
  }


  // Pass the order (commande)
  passerCommande(): void {
    if (this.selectedMedicaments.length === 0) return;  // ✅ Prevent empty orders

    const commande = {
      fournisseurId: this.fournisseurId,
      status: 'Encours',
      medicaments: this.selectedMedicaments
    };

    this.commandeService.passerCommande(commande).subscribe(
      response => {
        console.log('Commande passée avec succès', response);
        alert('Commande passée avec succès !');
        this.selectedMedicaments = []; // ✅ Clear the selection after ordering
      },
      error => {
        console.error('Erreur lors de la commande', error);
        alert('Erreur lors de la commande.');
      }
    );
  }
}
